import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.DlQ8ZhpE.js";const h=JSON.parse('{"title":"Features","description":"","frontmatter":{"title":"Features","order":2},"headers":[],"relativePath":"docs/features/index.md","filePath":"en/docs/features/index.md"}'),i={name:"docs/features/index.md"};function o(r,e,p,l,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>The stages a request passes through in Pavonis:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>select site by host / path_prefix ── no match ──► 404</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>static_files path ────────────────── match ────► resource limits ──► local file / static content</span></span>
<span class="line"><span>  │ no match</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>resource limits ──────────────────── exceeded ──► 429</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>client auth (if enabled) ─────────── failed ────► 401</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>header modification → outbound connection (IP pool / request proxy) ──► upstream</span></span>
<span class="line"><span>(uploads and downloads are subject to bandwidth limits)</span></span></code></pre></div><h2 id="site-modes" tabindex="-1">Site Modes <a class="header-anchor" href="#site-modes" aria-label="Permalink to &quot;Site Modes&quot;">​</a></h2><p>The core capability of Pavonis is expressed through <strong>site modes</strong>. A single instance can run any number of sites simultaneously, each choosing a mode that covers container images, code hosting, ML platforms, package management and more.</p><p>→ <a href="./../sites/">Site Modes Documentation</a></p><h2 id="static-files" tabindex="-1">Static Files <a class="header-anchor" href="#static-files" aria-label="Permalink to &quot;Static Files&quot;">​</a></h2><p>A site can serve a local file or fixed content directly at given paths, for example a homepage or a health check endpoint. These paths require no authentication, even if the site has client authentication enabled.</p><p>→ <a href="./../config/sites#staticfileconfig-static-files">StaticFileConfig Documentation</a></p><h2 id="outbound-ip-pool" tabindex="-1">Outbound IP Pool <a class="header-anchor" href="#outbound-ip-pool" aria-label="Permalink to &quot;Outbound IP Pool&quot;">​</a></h2><p>When your server holds a large IPv6 address block (e.g. a <code>/48</code> subnet from HE Tunnel Broker), you can enable the IP pool to let Pavonis select outbound IPs from the pool at random or by rule, effectively bypassing per-IP rate limits imposed by upstream platforms. Supports <code>random</code> and <code>ip_hash</code> (pinned by client IP) strategies, with per-site override support.</p><p>→ <a href="./ip-pool">IP Pool Documentation</a></p><h2 id="resource-limits" tabindex="-1">Resource Limits <a class="header-anchor" href="#resource-limits" aria-label="Permalink to &quot;Resource Limits&quot;">​</a></h2><p>Limit bandwidth, request rate and concurrent requests, per client or for all clients combined. Sites can also be put into quota groups to give different sites different quotas.</p><p>→ <a href="./rate-limiting">Resource Limits Documentation</a></p><h2 id="authentication-headers-and-request-proxy" tabindex="-1">Authentication, Headers and Request Proxy <a class="header-anchor" href="#authentication-headers-and-request-proxy" aria-label="Permalink to &quot;Authentication, Headers and Request Proxy&quot;">​</a></h2><p>Container registry and <code>any_url</code> sites support client authentication, with hot-reloadable user files (no restart required to update the user list). Automatically strips reverse-proxy-related headers to prevent leaking proxy chain information to upstreams. Upstream requests can go through one or more request proxies, with automatic switching when one is unreachable.</p><p>→ <a href="./auth-and-headers">Auth, Headers and Request Proxy Documentation</a></p>`,18)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
